import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} nonnegative reals x_1, x_2, ..., x_{alpha} are of the form x_n = a_n b_n with a_n nonnegative integers and b_n positive reals. They satisfy the three identities:\n1) (\\sum_{n=1}^{\\alpha} x_n)\\left( \\sum_{k=0}^{\\, {m1_minus_one}} \\frac{1}{(k+{m1_plus_one})({two_m1}-k)} \\right) = \\sum_{k=1}^{\\, {m1}} \\frac{1}{k(2k-1)}.\n2) \\frac{\\sum_{k=1}^{\\, {m2}} \\frac{1}{k(2k-1)}}{\\sum_{k=0}^{\\, {m2_minus_one}} \\frac{1}{(k+{m2_plus_one})({two_m2}-k)}} = 1 + \\sum_{n=1}^{\\alpha} x_n^2.\n3) \\left( \\sum_{k=0}^{\\, {m3_minus_one}} \\frac{1}{(k+{m3_plus_one})({two_m3}-k)} \\right)\\left( 2\\sum_{n=1}^{\\alpha} x_n^3 - 1 \\right) = \\sum_{k=1}^{\\, {m3}} \\frac{1}{k(2k-1)}.\nDetermine the minimum possible value of \\sum_{n=1}^{\\alpha} x_n^{\\, {p}}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# choose m1 so that alpha = 3*m1 + 1, with moderate size
# to keep expressions sizeable yet tractable in a statement
m1 = rng.randint(5, 900)
alpha = 3*m1 + 1
# choose p from a harder set {5,6}
p = rng.choice([5, 6])
# compute m2 and m3 to enforce moment relations
m2 = (alpha*alpha - 1) // 3
m3 = (2*alpha*alpha*alpha - 3*alpha - 2) // 3
# safety checks (integrality guaranteed by alpha ≡ 1 (mod 3))
if (alpha - 1) % 3 != 0:
    # retry if somehow not valid (shouldn't happen)
    return generator(rng)
if (alpha*alpha - 1) % 3 != 0:
    return generator(rng)
if (2*alpha*alpha*alpha - 3*alpha - 2) % 3 != 0:
    return generator(rng)
return {
    'alpha': alpha,
    'p': p,
    'm1': m1,
    'm1_minus_one': m1 - 1,
    'm1_plus_one': m1 + 1,
    'two_m1': 2*m1,
    'm2': m2,
    'm2_minus_one': m2 - 1,
    'm2_plus_one': m2 + 1,
    'two_m2': 2*m2,
    'm3': m3,
    'm3_minus_one': m3 - 1,
    'm3_plus_one': m3 + 1,
    'two_m3': 2*m3,
}

    def verifier(assign):
# Validate and compute the unique minimal value implied by the identities
# Returns (True, answer) with answer as a simplified rational string or int
try:
    from fractions import Fraction
    # required keys
    req = ['alpha','p','m1','m1_minus_one','m1_plus_one','two_m1','m2','m2_minus_one','m2_plus_one','two_m2','m3','m3_minus_one','m3_plus_one','two_m3']
    for k in req:
        if k not in assign:
            return (False, None)
    alpha = int(assign['alpha'])
    p = int(assign['p'])
    m1 = int(assign['m1'])
    m1m1 = int(assign['m1_minus_one'])
    m1p1 = int(assign['m1_plus_one'])
    t2m1 = int(assign['two_m1'])
    m2 = int(assign['m2'])
    m2m1 = int(assign['m2_minus_one'])
    m2p1 = int(assign['m2_plus_one'])
    t2m2 = int(assign['two_m2'])
    m3 = int(assign['m3'])
    m3m1 = int(assign['m3_minus_one'])
    m3p1 = int(assign['m3_plus_one'])
    t2m3 = int(assign['two_m3'])
    # domain checks
    if alpha <= 4:
        return (False, None)
    if (alpha - 1) % 3 != 0:
        return (False, None)
    if m1 != (alpha - 1)//3 or m1m1 != m1 - 1 or m1p1 != m1 + 1 or t2m1 != 2*m1:
        return (False, None)
    if m2 != (alpha*alpha - 1)//3 or m2m1 != m2 - 1 or m2p1 != m2 + 1 or t2m2 != 2*m2:
        return (False, None)
    if m3 != (2*alpha*alpha*alpha - 3*alpha - 2)//3 or m3m1 != m3 - 1 or m3p1 != m3 + 1 or t2m3 != 2*m3:
        return (False, None)
    if p not in (5,6):
        return (False, None)
    # Use the telescoping identity to interpret the constraints without summation.
    # For any positive integer m:
    # sum_{k=1}^m 1/[k(2k-1)] = 2(H_{2m} - H_m)
    # sum_{k=0}^{m-1} 1/((k+m+1)(2m - k)) = 2(H_{2m} - H_m)/(3m+1)
    # Hence their ratio is 3m + 1.
    # Therefore the three constraints force the moments to be:
    S1 = alpha                          # from ratio with m1: S1 = 3*m1 + 1 = alpha
    S2 = 3*m2                           # from ratio with m2: 1 + S2 = 3*m2 + 1
    S3 = Fraction(3*m3 + 2, 2)          # from ratio with m3: 2*S3 - 1 = 3*m3 + 1
    # Cross-check the hidden structure: S2 must equal alpha^2 - 1, S3 must equal alpha^3 - (3/2)alpha + 1/2
    if S2 != alpha*alpha - 1:
        return (False, None)
    if S3 != Fraction(alpha**3,1) - Fraction(3*alpha,2) + Fraction(1,2):
        return (False, None)
    # The minimizer of sum x_i^p subject to fixed S1, S2 and nonnegativity is attained when
    # at most two variables are positive; the third constraint pins the configuration to the
    # two-point extremal (equality case), yielding xy = (S1^2 - S2)/2 = 1/2.
    e1 = Fraction(S1, 1)
    e2 = Fraction(1, 2)
    # Compute power sums p_k = sum x_i^k for the two-point support using the recurrence
    # p_0 = 2, p_1 = e1, and p_k = e1*p_{k-1} - e2*p_{k-2}.
    p0 = Fraction(2,1)
    p1 = e1
    if p == 5:
        p2 = e1*p1 - e2*p0          # = S2, consistency check
        # optional consistency
        # if p2 != S2: return (False, None)
        p3 = e1*p2 - e2*p1          # = S3, consistency check
        # if p3 != S3: return (False, None)
        p4 = e1*p3 - e2*p2
        p5 = e1*p4 - e2*p3
        ans = p5
    elif p == 6:
        p2 = e1*p1 - e2*p0
        p3 = e1*p2 - e2*p1
        p4 = e1*p3 - e2*p2
        p5 = e1*p4 - e2*p3
        p6 = e1*p5 - e2*p4
        ans = p6
    else:
        return (False, None)
    # return answer as simplest form: integer if denominator 1, else 'num/den' string
    if ans.denominator == 1:
        return True, int(ans.numerator)
    else:
        return True, f"{ans.numerator}/{ans.denominator}"
except Exception:
    return (False, None)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

